module.exports = /*#__PURE__*/JSON.parse('[{"id":1,"title":"My First Hiking Adventure","excerpt":"A thrilling tale of my first hike up a challenging trail...","content":"On a crisp morning in early spring, I embarked on my first hiking adventure. The trail was steep, but the views from the summit were worth every step. I learned the importance of preparation and the joy of nature\'s quiet beauty...","slug":"first-hiking-adventure","image":"blog4.jpg","date":"2025-05-15"},{"id":2,"title":"Top 5 Hiking Trails","excerpt":"Discover the best trails around the world for your next adventure...","content":"From the rugged paths of the Appalachian Trail to the scenic routes of the Inca Trail, here are the top 5 hiking trails every enthusiast should explore. Each offers unique challenges and breathtaking scenery...","slug":"top-5-hiking-trails","image":"blog3.jpg","date":"2025-05-10"},{"id":3,"title":"Gear Guide for Beginners","excerpt":"Essential equipment for your first hike to ensure safety and comfort...","content":"Starting your hiking journey? You’ll need sturdy boots, a reliable backpack, and plenty of water. This guide covers the must-have gear to keep you safe and comfortable on the trails...","slug":"gear-guide-beginners","image":"1.jpg","date":"2025-05-12"},{"id":4,"title":"Hiking Safety Tips","excerpt":"Stay safe on your next hiking trip with these essential tips...","content":"Hiking is rewarding, but safety is key. Always tell someone your plans, carry a first-aid kit, and check the weather. These tips will help you enjoy your hike worry-free...","slug":"hiking-safety-tips","image":"blog1.jpg","date":"2025-05-18"},{"id":5,"title":"Wildlife Encounters on the Trails","excerpt":"Amazing wildlife I met on the trails during my hikes...","content":"While hiking through dense forests, I’ve encountered deer, eagles, and even a curious fox. These wildlife moments remind us to respect nature and observe from a distance...","slug":"wildlife-encounters","image":"blog2.jpg","date":"2025-05-20"}]');

